import React, { useState, useRef, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  Box, Typography, Paper, TextField, InputAdornment, IconButton, Chip,
  Avatar, Stack, CircularProgress,
} from '@mui/material';
import SendIcon from '@mui/icons-material/Send';
import SmartToyIcon from '@mui/icons-material/SmartToy';
import axiosInstance from '../../api/axiosConfig';
import { formatPersianNumber, toPersianDigits } from '../../utils/numberUtils';
import { toJalali } from '../../utils/dateUtils';

/**
 * دستیار HR — کاملاً آفلاین و سبک (Rule-based).
 * همهٔ اطلاعات از یک endpoint یکپارچه (/assistant/data/) مستقیماً از دیتابیس
 * خوانده و ترکیب می‌شوند. بدون مدل زبانی، بدون اینترنت.
 */
const HRAssistant = () => {
  const [messages, setMessages] = useState([
    {
      from: 'bot',
      text: 'سلام! 👋 من دستیار منابع انسانی هستم. می‌توانید درباره هر پرسنل، دپارتمان، حقوق، تولد و قرارداد از من بپرسید.',
    },
  ]);
  const [input, setInput] = useState('');
  const [typing, setTyping] = useState(false);
  const endRef = useRef(null);

  // Single consolidated call — fresh data from DB, cached by React Query.
  const { data: db } = useQuery({
    queryKey: ['assistant-data'],
    queryFn: () => axiosInstance.get('/assistant/data/').then(r => r.data),
    staleTime: 60 * 1000,
  });

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, typing]);

  const normalize = (s) => (s || '').toLowerCase().replace(/[‌\s]+/g, ' ').trim();

  /* ---------------------------------------------------------------------
   * Helpers: find a specific employee by name/employee code mentioned in
   * the question, combining multiple fields.
   * --------------------------------------------------------------------- */
  const findEmployee = (q) => {
    const list = db?.employees || [];
    if (!list.length) return null;
    // Try employee_id (exact)
    for (const e of list) {
      if (e.employee_id && q.includes(normalize(e.employee_id))) return e;
    }
    // Then first + last name
    let best = null;
    let bestScore = 0;
    for (const e of list) {
      const fn = normalize(e.first_name || '');
      const ln = normalize(e.last_name || '');
      let score = 0;
      if (fn && q.includes(fn)) score += 2;
      if (ln && q.includes(ln)) score += 3;
      if (score > bestScore) { bestScore = score; best = e; }
    }
    return best;
  };

  const gendersDisplay = (db?.genders || [])
    .filter(g => g.gender)
    .map(g => `${g.gender === 'male' ? 'مرد' : g.gender === 'female' ? 'زن' : g.gender}: ${formatPersianNumber(g.count)} نفر`).join('، ');

  const answerQuestion = (raw) => {
    const q = normalize(raw);

    if (!db) return 'در حال بارگذاری اطلاعات... لطفاً کمی صبر کنید.';

    const total = db.employees?.length || 0;
    const emp = findEmployee(q);

    // -------- پرسنل خاص (نام یا کد پرسنلی) --------
    if (emp) {
      // تولد
      if (/(تولد|متولد)/.test(q)) {
        return emp.birth_date
          ? `تاریخ تولد ${emp.full_name} (کد پرسنلی ${toPersianDigits(emp.employee_id)}): ${toJalali(emp.birth_date)} است.`
          : `متأسفانه تاریخ تولد ${emp.full_name} در سیستم ثبت نشده است.`;
      }
      // کل اطلاعات شخص
      if (/(کیست|کیه|مشخصات|اطلاعات|پروفایل|بگو)/.test(q) || (emp && !/[?؟]/.test(q))) {
        return [
          `👤 ${emp.full_name}`,
          emp.employee_id && `کد پرسنلی: ${toPersianDigits(emp.employee_id)}`,
          emp.national_id && `کد ملی: ${toPersianDigits(emp.national_id)}`,
          emp.department_name && `دپارتمان: ${emp.department_name}`,
          emp.job_title_name && `عنوان شغلی: ${emp.job_title_name}`,
          emp.work_location_name && `محل استقرار: ${emp.work_location_name}`,
          emp.gender && `جنسیت: ${emp.gender}`,
          emp.status && `وضعیت: ${emp.status}`,
          emp.birth_date && `تولد: ${toJalali(emp.birth_date)}`,
          emp.hire_date && `استخدام: ${toJalali(emp.hire_date)}`,
          emp.mobile && `موبایل: ${toPersianDigits(emp.mobile)}`,
          emp.contract_type_name && `نوع قرارداد: ${emp.contract_type_name}`,
          emp.contract_end_date && `پایان قرارداد: ${toJalali(emp.contract_end_date)}`,
        ].filter(Boolean).join('\n');
      }
      // دپارتمان شخص
      if (/(دپارتمان|بخش|واحد)/.test(q)) {
        return emp.department_name
          ? `${emp.full_name} در دپارتمان «${emp.department_name}» است.`
          : `دپارتمان ${emp.full_name} ثبت نشده است.`;
      }
      // عنوان شغلی شخص
      if (/(شغل|سمت|عنوان)/.test(q)) {
        return emp.job_title_name
          ? `عنوان شغلی ${emp.full_name} «${emp.job_title_name}» است.`
          : `عنوان شغلی ${emp.full_name} ثبت نشده است.`;
      }
      // نوع قرارداد شخص
      if (/(قرارداد)/.test(q)) {
        const parts = [];
        if (emp.contract_type_name) parts.push(`نوع قرارداد ${emp.full_name}: ${emp.contract_type_name}`);
        if (emp.contract_end_date) parts.push(`پایان قرارداد: ${toJalali(emp.contract_end_date)}`);
        return parts.length ? parts.join('\n') : `قراردادی برای ${emp.full_name} ثبت نشده است.`;
      }
      // موبایل شخص
      if (/(موبایل|تلفن|شماره|تماس)/.test(q)) {
        return emp.mobile
          ? `شماره موبایل ${emp.full_name}: ${toPersianDigits(emp.mobile)}`
          : `موبایلی برای ${emp.full_name} ثبت نشده است.`;
      }
      // default: show profile
      return `👤 ${emp.full_name}\nکد پرسنلی: ${toPersianDigits(emp.employee_id)}${emp.department_name ? `\nدپارتمان: ${emp.department_name}` : ''}${emp.job_title_name ? `\nعنوان شغلی: ${emp.job_title_name}` : ''}`;
    }

    // -------- سؤالات سراسری --------
    if (/(چند|تعداد|چه تعداد).*(پرسنل|نفر|کارمند|کارکن)/.test(q) || /پرسنل.*(چند|تعداد)/.test(q)) {
      return `در حال حاضر ${formatPersianNumber(total)} پرسنل فعال در سازمان ثبت شده است.`;
    }

    if (/(بخش|دپارتمان|واحد)/.test(q)) {
      const list = db.departments || [];
      if (!list.length) return 'دپارتمانی ثبت نشده است.';
      const top = [...list].sort((a, b) => b.count - a.count)[0];
      if (/(بیشترین|بزرگ‌ترین|بیشتر)/.test(q)) {
        return `بزرگ‌ترین دپارتمان «${top.name}» با ${formatPersianNumber(top.count)} نفر است.`;
      }
      return `توزیع پرسنل در دپارتمان‌ها: ${list.map(d => `${d.name} (${formatPersianNumber(d.count)})`).join('، ')}`;
    }

    if (/(جنسیت|زن|مرد|خانم|آقا)/.test(q)) {
      return gendersDisplay ? `ترکیب جنسیتی: ${gendersDisplay}` : 'اطلاعات جنسیتی ثبت نشده است.';
    }

    if (/(خروج|ترک خدمت|اخراج|بازنشست)/.test(q)) {
      const t = db.turnover || {};
      return `نرخ ترک خدمت ${formatPersianNumber(t.rate ?? 0)}٪ است (${formatPersianNumber(t.terminated_count ?? 0)} خروج در این سال).`;
    }

    if (/(سن)/.test(q)) {
      // average age from birth_date
      const withBirth = (db.employees || []).filter(e => e.birth_date);
      if (withBirth.length) {
        const years = withBirth.map(e => {
          const b = new Date(e.birth_date);
          return (Date.now() - b.getTime()) / (365.25 * 24 * 3600 * 1000);
        });
        const avg = Math.round(years.reduce((s, y) => s + y, 0) / years.length);
        return `میانگین سن پرسنل حدود ${formatPersianNumber(avg)} سال است.`;
      }
      return 'تاریخ تولد پرسنلی ثبت نشده است تا میانگین سن محاسبه شود.';
    }

    if (/(تولد|متولد)/.test(q)) {
      const b = db.birthdays || [];
      if (!b.length) return 'در ۷ روز آینده تولدی ثبت نشده است.';
      return `تولدهای ۷ روز آینده:\n${b.map(x => `• ${x.full_name} (${x.is_today ? 'امروز 🎂' : `${toPersianDigits(x.days_until)} روز دیگر`})`).join('\n')}`;
    }

    if (/(قرارداد|انقضا|پایان قرارداد)/.test(q)) {
      const c = db.contracts_expiring || [];
      if (!c.length) return 'در ۹۰ روز آینده قراردادی منقضی نمی‌شود.';
      return `${formatPersianNumber(c.length)} قرارداد در شرف انقضا هستند:\n${c.slice(0, 8).map(x => `• ${x.full_name} (${toJalali(x.contract_end_date)})`).join('\n')}`;
    }

    if (/(محل استقرار|شعبه|محل کار|مکان)/.test(q)) {
      const list = db.locations || [];
      if (!list.length) return 'محل استقراری ثبت نشده است.';
      const top = [...list].sort((a, b) => b.count - a.count)[0];
      return `محل استقرار «${top.name}» با ${formatPersianNumber(top.count)} نفر، بزرگ‌ترین شعبه است.`;
    }

    if (/(عنوان شغلی|سمت|شغل)/.test(q)) {
      const list = db.job_titles || [];
      if (!list.length) return 'عنوان شغلی ثبت نشده است.';
      const top = [...list].sort((a, b) => b.count - a.count)[0];
      return `عنوان شغلی «${top.name}» با ${formatPersianNumber(top.count)} نفر، رایج‌ترین سمت است.`;
    }

    if (/(حقوق|مزایا|پرداخت|کسور)/.test(q)) {
      const s = db.salary || {};
      return `جمع حقوق پرداختی ${formatPersianNumber(s.total_payable ?? 0)} ریال و جمع کسورات ${formatPersianNumber(s.total_deductions ?? 0)} ریال است.`;
    }

    if (/(مکاتب|نامه|ابلاغ|فرم)/.test(q)) {
      const c = db.correspondences || {};
      return `در سیستم: ${formatPersianNumber(c.incoming ?? 0)} نامه وارده، ${formatPersianNumber(c.outgoing ?? 0)} نامه صادره، ${formatPersianNumber(c.announcements ?? 0)} ابلاغ و ${formatPersianNumber(c.forms ?? 0)} فرم ثبت شده است.`;
    }

    if (/(مدرک|سند)/.test(q)) {
      const d = db.documents || {};
      return `در مجموع ${formatPersianNumber(d.total ?? 0)} مدرک ثبت شده است (${formatPersianNumber(d.expired ?? 0)} مدرک منقضی).`;
    }

    if (/(سلام|درود|هی)/.test(q)) {
      return 'سلام! از من درباره هر پرسنل (مثلاً «رضا کیست؟» یا «تولد علی کیه؟»)، دپارتمان‌ها، حقوق، قراردادها و مکاتبات بپرسید.';
    }

    if (/(ممنون|تشکر|مرسی|سپاس)/.test(q)) {
      return 'خواهش می‌کنم! اگر سؤال دیگری دارید در خدمتم. 😊';
    }

    return 'می‌توانید مثلاً بپرسید: «تولد [نام پرسنل] کیه؟»، «[نام] کیست؟»، «تعداد پرسنل چقدره؟»، «نرخ خروج چقدره؟»، «قراردادها چطوره؟»';
  };

  const send = (text) => {
    const question = text || input.trim();
    if (!question) return;
    setMessages(prev => [...prev, { from: 'user', text: question }]);
    setInput('');
    setTyping(true);
    setTimeout(() => {
      setMessages(prev => [...prev, { from: 'bot', text: answerQuestion(question) }]);
      setTyping(false);
    }, 300);
  };

  const suggestions = [
    'تعداد پرسنل چقدر است؟',
    'نرخ خروج چقدره؟',
    'تولدهای ۷ روز آینده کیان؟',
    'کدوم دپارتمان بزرگ‌ترینه؟',
    'وضعیت قراردادها چطوره؟',
  ];

  return (
    <Paper sx={{
      overflow: 'hidden',
      maxWidth: 700,
      width: '100%',
      background: 'linear-gradient(135deg, rgba(99,102,241,0.08), rgba(236,72,153,0.04))',
      border: '1px solid rgba(99,102,241,0.2)',
      backdropFilter: 'blur(18px)', WebkitBackdropFilter: 'blur(18px)',
      borderRadius: 3,
    }}>
      {/* Header */}
      <Box sx={{
        px: 2.5, py: 1.5,
        background: 'linear-gradient(135deg, rgba(99,102,241,0.14), rgba(236,72,153,0.08))',
        borderBottom: '1px solid rgba(99,102,241,0.16)',
        display: 'flex', alignItems: 'center', gap: 1.5,
      }}>
        <Avatar sx={{ width: 40, height: 40, background: 'linear-gradient(135deg, #6366f1, #ec4899)', boxShadow: '0 3px 12px rgba(99,102,241,0.4)' }}>
          <SmartToyIcon sx={{ color: '#fff', fontSize: 22 }} />
        </Avatar>
        <Box>
          <Typography variant="subtitle1" fontWeight={700}>دستیار منابع انسانی</Typography>
          <Typography variant="caption" color="textSecondary">پاسخ فوری و آفلاین از داده‌های سازمان</Typography>
        </Box>
      </Box>

      {/* Messages */}
      <Box sx={{ p: 2, minHeight: 300, maxHeight: 50 + 'vh', overflowY: 'auto' }}>
        <Stack spacing={1.5}>
          {messages.map((m, i) => (
            <Box key={i} sx={{ display: 'flex', justifyContent: m.from === 'user' ? 'flex-start' : 'flex-end' }}>
              <Paper sx={{
                px: 1.5, py: 1, maxWidth: '80%',
                background: m.from === 'user'
                  ? 'linear-gradient(135deg, rgba(99,102,241,0.9), rgba(139,92,246,0.9))'
                  : 'rgba(255,255,255,0.65)',
                color: m.from === 'user' ? '#fff' : 'text.primary',
                borderRadius: '14px 14px 4px 14px',
                border: m.from === 'user' ? 'none' : '1px solid rgba(99,102,241,0.16)',
              }}>
                <Typography variant="body2" sx={{ whiteSpace: 'pre-line', textAlign: m.from === 'user' ? 'right' : 'right' }}>{m.text}</Typography>
              </Paper>
            </Box>
          ))}
          {typing && (
            <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
              <Paper sx={{ px: 1.5, py: 1, background: 'rgba(255,255,255,0.65)', borderRadius: '14px 14px 4px 14px' }}>
                <Box sx={{ display: 'flex', gap: 0.5 }}>
                  <CircularProgress size={12} /><CircularProgress size={12} /><CircularProgress size={12} />
                </Box>
              </Paper>
            </Box>
          )}
          <div ref={endRef} />
        </Stack>
      </Box>

      {/* Suggestions */}
      <Box sx={{ px: 2, pb: 1, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
        {suggestions.map(s => (
          <Chip key={s} label={s} size="small" variant="outlined" clickable onClick={() => send(s)}
            sx={{ borderColor: 'rgba(99,102,241,0.35)', color: '#6366f1' }} />
        ))}
      </Box>

      {/* Input */}
      <Box sx={{ p: 2, pt: 1, borderTop: '1px solid rgba(99,102,241,0.12)' }}>
        <TextField
          fullWidth
          size="small"
          placeholder="مثلاً: تولد رضا محمدی کیه؟"
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter') send(); }}
          InputProps={{
            endAdornment: (
              <InputAdornment position="end">
                <IconButton size="small" color="primary" onClick={() => send()}>
                  <SendIcon fontSize="small" />
                </IconButton>
              </InputAdornment>
            ),
          }}
        />
      </Box>
    </Paper>
  );
};

export default HRAssistant;
